INSERT INTO public.exercises (id, name, muscle_group, secondary_muscles, equipment, instructions, is_custom) VALUES
('ex-bench-press', 'Barbell Bench Press', 'Chest', '["Triceps", "Shoulders"]'::jsonb, 'Barbell', 'Lie back on a flat bench. Grip barbell slightly wider than shoulder-width. Lower bar to mid-chest, press up explosively.', false),
('ex-incline-db-press', 'Incline Dumbbell Press', 'Chest', '["Shoulders", "Triceps"]'::jsonb, 'Dumbbell', 'Set bench to 30-45 degrees. Press dumbbells upward, squeezing upper pecs at the peak.', false),
('ex-decline-bench-press', 'Decline Barbell Bench Press', 'Chest', '["Triceps"]'::jsonb, 'Barbell', 'Secured on decline bench. Lower to lower chest, press upward.', false),
('ex-flat-db-press', 'Flat Dumbbell Press', 'Chest', '["Triceps", "Shoulders"]'::jsonb, 'Dumbbell', 'Dumbbells at chest level. Press up with controlled arc.', false),
('ex-cable-crossover', 'Cable Crossover / Fly', 'Chest', '["Shoulders"]'::jsonb, 'Cable', 'High-to-low or mid-height pulley. Hug arms inward focusing on chest squeeze.', false),
('ex-pec-deck', 'Pec Deck / Chest Fly Machine', 'Chest', '[]'::jsonb, 'Machine', 'Keep elbows slightly bent. Contract pecs to bring pads/handles together.', false),
('ex-chest-dip', 'Chest Dips', 'Chest', '["Triceps", "Shoulders"]'::jsonb, 'Bodyweight', 'Lean torso forward 30 degrees, flare elbows slightly, dip down until 90 degree arm angle.', false),
('ex-push-up', 'Push-Up', 'Chest', '["Triceps", "Core"]'::jsonb, 'Bodyweight', 'Hands shoulder-width apart, rigid core. Lower chest to floor and press.', false),
('ex-incline-barbell-press', 'Incline Barbell Bench Press', 'Chest', '["Shoulders", "Triceps"]'::jsonb, 'Barbell', 'Set bench to 30 degrees. Lower to upper chest, press vertically.', false),
('ex-smith-bench-press', 'Smith Machine Bench Press', 'Chest', '["Triceps"]'::jsonb, 'Smith Machine', 'Fixed bar path allows maximal isolation of pectoralis major.', false),
('ex-deadlift', 'Conventional Barbell Deadlift', 'Back', '["Hamstrings", "Glutes", "Forearms"]'::jsonb, 'Barbell', 'Feet hip-width, grip just outside knees. Hips back, neutral spine, pull floor away.', false),
('ex-barbell-row', 'Bent-Over Barbell Row', 'Back', '["Biceps", "Forearms"]'::jsonb, 'Barbell', 'Hinge forward 45-70 degrees. Row bar to lower ribcage pulling with elbows.', false),
('ex-pull-up', 'Pull-Up', 'Back', '["Biceps"]'::jsonb, 'Bodyweight', 'Overhand grip wider than shoulders. Pull chin over bar by engaging lats.', false),
('ex-chin-up', 'Chin-Up', 'Back', '["Biceps"]'::jsonb, 'Bodyweight', 'Underhand shoulder-width grip. Great lat sweep and bicep activation.', false),
('ex-lat-pulldown', 'Lat Pulldown', 'Back', '["Biceps"]'::jsonb, 'Cable', 'Wide grip. Pull bar to upper chest while maintaining upright posture.', false),
('ex-seated-cable-row', 'Seated Cable Row', 'Back', '["Biceps"]'::jsonb, 'Cable', 'Use V-bar or neutral grip. Pull to navel, squeeze shoulder blades together.', false),
('ex-one-arm-db-row', 'One-Arm Dumbbell Row', 'Back', '["Biceps", "Core"]'::jsonb, 'Dumbbell', 'Support knee on bench. Row dumbbell towards hip keeping back flat.', false),
('ex-t-bar-row', 'T-Bar Row', 'Back', '["Biceps"]'::jsonb, 'Machine', 'Chest supported or standing landmine. Pull handle towards sternum.', false),
('ex-face-pull', 'Cable Face Pull', 'Back', '["Shoulders"]'::jsonb, 'Cable', 'Rope attachment at eye level. Pull towards face while rotating hands outward.', false),
('ex-overhead-press', 'Overhead Barbell Press (OHP)', 'Shoulders', '["Triceps", "Core"]'::jsonb, 'Barbell', 'Standing tall with tight glutes. Press bar vertically overhead, locking out.', false),
('ex-seated-db-shoulder-press', 'Seated Dumbbell Shoulder Press', 'Shoulders', '["Triceps"]'::jsonb, 'Dumbbell', 'Sit on upright bench. Press dumbbells overhead with neutral or pronated grip.', false),
('ex-lateral-raise', 'Dumbbell Lateral Raise', 'Shoulders', '[]'::jsonb, 'Dumbbell', 'Raise arms out to sides until parallel to floor. Lead with elbows, control descent.', false),
('ex-cable-lateral-raise', 'Cable Lateral Raise', 'Shoulders', '[]'::jsonb, 'Cable', 'Continuous tension on lateral deltoid throughout the movement range.', false),
('ex-rear-delt-fly', 'Reverse Pec Deck / Rear Delt Fly', 'Shoulders', '["Back"]'::jsonb, 'Machine', 'Target posterior deltoid by pulling handles outward horizontally.', false),
('ex-barbell-squat', 'Barbell Back Squat', 'Quads', '["Glutes", "Hamstrings", "Core"]'::jsonb, 'Barbell', 'Bar rested on traps. Break at hips and knees, descend below parallel, drive up.', false),
('ex-front-squat', 'Barbell Front Squat', 'Quads', '["Core", "Glutes"]'::jsonb, 'Barbell', 'Bar in front rack position. Upright torso, deep knee flexion.', false),
('ex-leg-press', 'Leg Press', 'Quads', '["Glutes"]'::jsonb, 'Machine', 'Feet shoulder-width on carriage. Lower weight until 90 degrees knee bend, press.', false),
('ex-hack-squat', 'Hack Squat Machine', 'Quads', '["Glutes"]'::jsonb, 'Machine', 'Great quad quad recruitment with back fully stabilized.', false),
('ex-leg-extension', 'Leg Extension', 'Quads', '[]'::jsonb, 'Machine', 'Isolate quadriceps. Extend legs fully, pause at top contraction.', false),
('ex-romanian-deadlift', 'Romanian Deadlift (RDL)', 'Hamstrings', '["Glutes", "Back"]'::jsonb, 'Barbell', 'Slight knee bend. Hinge at hips pushing butt back until deep hamstring stretch.', false),
('ex-lying-leg-curl', 'Lying Leg Curl', 'Hamstrings', '[]'::jsonb, 'Machine', 'Curl heels towards glutes smoothly. Control the negative.', false),
('ex-hip-thrust', 'Barbell Hip Thrust', 'Glutes', '["Hamstrings"]'::jsonb, 'Barbell', 'Upper back on bench, barbell across hips. Drive hips up, lock out with glutes.', false),
('ex-standing-calf-raise', 'Standing Calf Raise', 'Calves', '[]'::jsonb, 'Machine', 'Balls of feet on block. Deep stretch at bottom, press up onto toes high.', false),
('ex-barbell-curl', 'Barbell Bicep Curl', 'Biceps', '["Forearms"]'::jsonb, 'Barbell', 'Shoulder-width underhand grip. Curl bar without swinging elbows.', false),
('ex-ez-bar-curl', 'EZ-Bar Curl', 'Biceps', '[]'::jsonb, 'Barbell', 'Angled grip reduces wrist strain while overloading biceps.', false),
('ex-hammer-curl', 'Dumbbell Hammer Curl', 'Biceps', '["Forearms"]'::jsonb, 'Dumbbell', 'Neutral palms facing each other. Emphasizes brachialis and forearms.', false),
('ex-tricep-rope-pushdown', 'Cable Tricep Rope Pushdown', 'Triceps', '[]'::jsonb, 'Cable', 'Spread rope ends at bottom lockout. Keep elbows pinned to sides.', false),
('ex-skull-crusher', 'Barbell Skull Crusher / Lying Extension', 'Triceps', '[]'::jsonb, 'Barbell', 'Lie on flat bench. Lower bar to forehead/top of head, extend elbows.', false),
('ex-hanging-leg-raise', 'Hanging Leg Raise', 'Core', '[]'::jsonb, 'Bodyweight', 'Hang from pull-up bar. Raise straight legs or knees to parallel without swinging.', false)
